<template>
	<view class="">
		<view class="head">
			<view class="head_top d-flex a-center j-sb">
				<view class="head_top_ipt">
					<u-search @clear='goodsListApi()' shape="square" @search="goodsListApi" :showAction='false'
						placeholder="请输入商品名" v-model="keyword"></u-search>
				</view>
				<view class="head_btn" @click="routerTo('/pagesD/ShelfGoods/ShelfGoods')">
					上架商品
				</view>
			</view>
			<view class="">
				<u-tabs lineWidth="30" @click="tabclick"
					:activeStyle="{color: '#303133', fontWeight: 'bold',  transform: 'scale(1.08)' }" lineHeight="5"
					lineColor="#036045" :list="tabList"></u-tabs>
			</view>
		</view>
		<view class="u-wrap">
			<view class="u-menu-wrap">
				<scroll-view scroll-y scroll-with-animation class="u-tab-view menu-scroll-view" :scroll-top="scrollTop">
					<view class="" style="background-color: #fff;">
						<view v-for="(item, index) in list" :key="index" class="u-tab-item"
							:class="[current == index ? 'u-tab-item-active' : '',current+1 == index ? 'topRouend' : '',current - 1 == index ? 'bomRouend' : '']"
							:data-current="index" @tap.stop="swichMenu(item, index)">
							<view class="u-line-2 " style="padding: 0 10rpx;box-sizing: border-box;">{{item.name}}
							</view>
						</view>
					</view>

				</scroll-view>

				<scroll-view scroll-y class="right-box">
					<empty v-if="shopList.length==0"></empty>
					<view class="right-box_item d-flex  j-sb" v-for="(item,index) in shopList" :key="index">
						<view class="right-box_item_left">
							<image :src="item.image" mode="aspectFill"></image>
						</view>
						<view class="right-box_item_right">
							<view class="beyond-two f-bold color-3d f-size-24">
								{{item.title}}
							</view>
							<view class="tab_box d-flex a-center mt-10 mb-10">
								<view class="tab_item" v-for="item_1 in item.tags" :key="item_1">
									{{item_1}}
								</view>
							</view>
							<view class="f-size-32 color-3d mt-10 mb-10 f-bold">
								¥{{item.minprice}}
							</view>
							<view class="right_btn_box d-flex a-center pl-50">
								<view class="right_btn" v-if="item.state==1" @click="goodsStatusSwitchApi(0,item.id)">
									下架
								</view>
								<view class="right_btn" v-else @click="goodsStatusSwitchApi(1,item.id)">
									上架
								</view>
								<view class="right_btn" @click="routerTo('/pagesD/ShelfGoods/ShelfGoods?id='+item.id)">
									编辑
								</view>
							</view>
						</view>
					</view>
				</scroll-view>
			</view>


		</view>
	</view>
</template>

<script>
	export default {
		name: 'fa-category',

		data() {
			return {
				current: 0,
				category: 10,
				tabList: [{
					name: '全部',
					id: -1
				}, {
					name: '已上架',
					id: 1
				}, {
					name: '已下架',
					id: 0
				}],
				state: -1,
				keyword: '',
				list: [],
				shopList: []
			};
		},
		onShow() {
			this.goodsListApi()
		},
		onLoad() {},
		methods: {
			// 商品上下假
			async goodsStatusSwitchApi(state, id) {
				let res = await this.goodsStatusSwitch({
					state: state,
					id
				})
				if (res.code == 1) {
					this.goodsListApi()
					// this.shopList.forEach((item, index) => {
					// 	if (item.id == id) {
					// 		// this.shopList.splice(index, 1)
					// 		if (state == 1) {
					// 			item.state = 0
					// 		} else {
					// 			item.state = 1
					// 		}
					// 	}
					// 	console.log(item)
					// })
					// this.$forceUpdate()
				}
			},
			tabclick(e) {
				console.log('ee', e);
				this.state = e.id
				this.goodsListApi()
			},
			async goodsListApi(e) {
				// if(e!==1){
				// 	this.page=1
				// }
				let res = await this.goodsList({
					search: this.keyword,
					state: this.state
				})
				if (res.code == 1) {
					this.list = res.data
					this.shopList = res.data[this.current].goods
				}
			},

			swichMenu(item, index) {
				this.current = index
				this.goodsListApi()
			},
			async categoryListApi() {
				let res = await this.categoryList()
				if (res.code == 1) {
					this.category = res.data.rows
				}
			}
		}
	};
</script>

<style lang="scss" scoped>
	.head {
		height: 150rpx;
		background-color: #fff;
		padding: 0 25rpx;

		.head_top {
			.head_top_ipt {
				width: 489rpx;
			}

			.head_btn {
				width: 197rpx;
				height: 60rpx;
				background: #036045;
				border-radius: 8rpx;
				text-align: center;
				line-height: 60rpx;
				font-size: 24rpx;
				color: #FFFFFF;
			}
		}
	}

	.u-wrap {
		height: calc(100vh - 150rpx);
		display: flex;
		flex-direction: column;
	}

	.u-menu-wrap {
		flex: 1;
		display: flex;
		overflow: hidden;

	}

	.u-tab-view {
		width: 200rpx;
		height: 100%;
		background-color: #f6f6f6;
	}

	.u-tab-item {
		height: 110rpx;
		box-sizing: border-box;
		display: flex;
		align-items: center;
		justify-content: center;
		font-size: 24rpx;
		color: #87888B;
		font-weight: 400;
		line-height: 1;
		background-color: #f6f6f6;
	}

	.u-tab-item-active {
		position: relative;
		color: #87888B;
		font-size: 24rpx;
		background: #fff;
	}



	.topRouend {
		border-top-right-radius: 40rpx;
	}

	.bomRouend {
		border-bottom-right-radius: 40rpx;
	}

	.u-tab-view {
		height: 100%;
	}

	.right-box {
		background-color: #fff;
		width: calc(100vw - 200rpx);

		.right-box_item {
			padding: 30rpx 20rpx;
			box-sizing: border-box;

			.right-box_item_left {
				image {
					border: 1rpx solid #eee;
					width: 128rpx;
					height: 128rpx;
					border-radius: 10rpx;
				}
			}

			.right-box_item_right {
				width: calc(100% - 150rpx);

				.tab_box {
					.tab_item {
						margin-right: 16rpx;
						padding: 4rpx 16rpx;
						box-sizing: border-box;
						background: #ECF3FF;
						border-radius: 6rpx;
						font-weight: 400;
						font-size: 20rpx;
						color: #036045;

					}
				}

				.right_btn_box {
					.right_btn {
						margin-left: 16rpx;
						width: 142rpx;
						height: 53rpx;
						border-radius: 969rpx;
						border: 2rpx solid #d0d0d0;
						font-size: 24rpx;
						color: #696A6F;
						line-height: 53rpx;
						text-align: center;
					}
				}

			}
		}
	}

	.page-view {}
</style>